from fractions import Fraction as F
rows=[('A',13,(1,0,0,0)),('A',3,(0,0,0,1)),('B',9,(1,0,1,0)),('B',5,(0,0,1,1)),('C',5,(1,1,1,0)),('C',8,(0,0,1,0)),('D',6,(1,0,0,0)),('D',5,(0,0,1,1))]
tests='TUVW'
cost=list(map(F,['1.8','1.5','1.2','0.8']))
L=[[0,11,6,16],[22,0,20,8],[16,23,0,7],[18,11,20,0]]
def stop(S):
    w=sum(rows[i][1] for i in S)
    return min((F(sum(rows[i][1]*L[a]['ABCD'.index(rows[i][0])] for i in S),w),'ABCD'[a]) for a in range(4))
def best(S,avail,n):
    options=[stop(S)]
    if n:
        for t in avail:
            options.append((testval(S,avail,n,t),tests[t]))
    return min(options)
def testval(S,avail,n,t):
    w=sum(rows[i][1] for i in S)
    v=cost[t]
    for b in (0,1):
        sub=[i for i in S if rows[i][2][t]==b]
        if sub:
            v+=F(sum(rows[i][1] for i in sub),w)*best(sub,[a for a in avail if a!=t],n-1)[0]
    return v
S=list(range(8))
vals={'STOP':stop(S)[0]}
for t in range(4): vals[tests[t]]=testval(S,list(range(4)),2,t)
first=best(S,list(range(4)),2)
print({k:float(v) for k,v in vals.items()})
print(first)
t=tests.index(first[1])
for b in (0,1):
    sub=[i for i in S if rows[i][2][t]==b]
    print(b,best(sub,[a for a in range(4) if a!=t],1))

